using System.Text;
namespace PoloOS.Diagnostics.Core;
public sealed record Kw1281Block(IReadOnlyList<byte> Bytes)
{
    public byte Length=>Bytes[0]; public byte Counter=>Bytes[1]; public byte Title=>Bytes[2]; public IReadOnlyList<byte> Body=>Bytes.Skip(3).Take(Bytes.Count-4).ToArray(); public bool IsAckNak=>Title is 0x09 or 0x0A; public string Hex=>string.Join(" ",Bytes.Select(b=>b.ToString("X2")));
    public string Ascii { get { var sb=new StringBuilder(); foreach(var b in Body){var v=b&0x7F;if(v is >=32 and <=126)sb.Append((char)v);else if(v!=0)sb.Append(' ');} return string.Join(" ",sb.ToString().Split(' ',StringSplitOptions.RemoveEmptyEntries)); } }
}
public sealed class Kw1281Dialog
{
    private const int R6=5; private readonly KwpCommon _common; private readonly DiagLog _log; private byte? _blockCounter;
    public Kw1281Dialog(KwpCommon common,DiagLog log){_common=common;_log=log;}
    public IReadOnlyList<Kw1281Block> Connect(){_blockCounter=null;return ReceiveBlocks();}
    public IReadOnlyList<Kw1281Block> ReceiveBlocks(){var blocks=new List<Kw1281Block>();while(true){var block=ReceiveBlock();blocks.Add(block);_log.Write($"KW1281_RX {block.Hex}");if(block.IsAckNak)break;SendAckBlock();}return blocks;}
    public Kw1281Block ReceiveBlock(){var bytes=new List<byte>();var length=ReadAndAckFirstByte();if(length<3||length>96)throw new InvalidOperationException($"Invalid KW1281 block length {length:X2}.");bytes.Add(length);var counter=ReadBlockCounter();bytes.Add(counter);var title=ReadAndAckByte();bytes.Add(title);for(var i=0;i<length-3;i++)bytes.Add(ReadAndAckByte());var end=_common.ReadByte(1800);bytes.Add(end);if(end!=0x03)throw new InvalidOperationException($"KW1281 block end expected 03, got {end:X2}. Partial={string.Join(" ",bytes.Select(x=>x.ToString("X2")))}");return new Kw1281Block(bytes);}
    public void SendBlock(params byte[] body){Thread.Sleep(25);var block=new List<byte>(body.Length+2){checked((byte)(body.Length+2)),_blockCounter??throw new InvalidOperationException("KW1281 block counter is not initialized.")};_blockCounter++;block.AddRange(body);PreciseDelay.Milliseconds(R6);foreach(var b in block){WriteByteAndReadAck(b);PreciseDelay.Milliseconds(R6);}_common.WriteByte(0x03);_log.Write($"KW1281_TX {string.Join(" ",block.Select(x=>x.ToString("X2")))} 03");}
    public Kw1281GroupSample? ReadGroup(byte group){SendBlock(0x29,group);var block=ReceiveBlock();_log.Write($"KW1281_GROUP_RX group={group:D3} {block.Hex}");if(block.Title==0x0A)return null;if(block.Title!=0xE7)throw new InvalidOperationException($"Group {group:D3}: expected E7/NAK, got {block.Title:X2}.");if(block.Body.Count%3!=0)throw new InvalidOperationException($"Group {group:D3}: E7 body length {block.Body.Count} is not multiple of 3.");var values=new List<Kw1281SensorValue>();for(var i=0;i+2<block.Body.Count;i+=3)values.Add(new Kw1281SensorValue(block.Body[i],block.Body[i+1],block.Body[i+2]));var sample=new Kw1281GroupSample(group,values,block.Body.ToArray());_log.Write($"KW1281_GROUP {sample}");return sample;}
    public IReadOnlyList<DtcEntry> ReadFaultCodes(){SendBlock(0x07);var blocks=ReceiveBlocks();var result=new List<DtcEntry>();foreach(var block in blocks.Where(b=>b.Title==0xFC)){var body=block.Body;for(var i=0;i+2<body.Count;i+=3){var hi=body[i];var lo=body[i+1];var status=body[i+2];if(hi==0xFF&&lo==0xFF&&status==0x88)continue;result.Add(new DtcEntry((hi<<8)|lo,status));}}return result;}
    private void SendAckBlock()=>SendBlock(0x09); private void WriteByteAndReadAck(byte value){_common.WriteByte(value);_common.ReadComplement(value);} private byte ReadBlockCounter(){var counter=ReadAndAckByte();if(!_blockCounter.HasValue)_blockCounter=counter;else if(counter!=_blockCounter.Value)throw new InvalidOperationException($"KW1281 counter expected {_blockCounter.Value:X2}, got {counter:X2}.");_blockCounter++;return counter;} private byte ReadAndAckByte(){var value=_common.ReadByte(1800);PreciseDelay.Milliseconds(R6);_common.WriteByte((byte)~value);return value;}
    private byte ReadAndAckFirstByte(int repeatCount=0){if(repeatCount>5)throw new InvalidOperationException("Unable to sync KW1281 after repeated 55 keyword sequences.");var value=_common.ReadByte(2500);if(value==0x55){_=_common.ReadByte(1000);var keywordMsb=_common.ReadByte(1000);PreciseDelay.Milliseconds(25);_common.WriteByte((byte)~keywordMsb);_log.Write("KW1281_REPEAT_SYNC");return ReadAndAckFirstByte(repeatCount+1);}PreciseDelay.Milliseconds(R6);_common.WriteByte((byte)~value);return value;}
}
